import {geographyHref} from './geography-base.mjs';
import {CASPIAN_FERRY,OBSERVED_KL896,AMS_ROAD,DUBAI_ROAD} from './network-tracks.mjs';
import {greatCircle,TERMINALS} from './maritime-paths.mjs';
import {DUBAI_FLIGHT} from './maritime-paths.mjs';
import { ROUTES } from './model.mjs';
import { roundedRoutePath, routeDirections, routeRelation } from './route-geometry.mjs';
import { routeLocations } from './map-layout.mjs';
const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mapInstance=0;
const labels = {suez:'Suez Canal',cape:'Cape of Good Hope',rail:'Middle Corridor',eco:'Slow steaming',seaair:'Sea–air via Dubai',air:'Direct air'};

export function mapLegend(route, referenceId, icon,referenceLabel="Baseline",showRecorded=false) {
  const baseline=ROUTES.find(item=>item.id===referenceId),relation=routeRelation(route,baseline);
  const kind={air:'Air link dashed · Not a flight track',rail:'Rail network · Ferry link dashed',multimodal:'Road network · Air link dashed'}[route.mode]||{air:'Reference air link · Track varies',rail:'Reference rail network',multimodal:'Reference air link dashed'}[baseline.mode];
  const item=(r,role,label)=>`<button class="map-legend-item ${role}" data-action="select" data-value="${r.id}" data-focus="map-legend-${r.id}" aria-label="View ${label.toLowerCase()} route ${escape(r.name)}"><i class="route-sample"></i><span><small>${label}</small><strong>${escape(labels[r.id])}</strong></span>${icon('arrow',13)}</button>`;
  return `<div class="map-route-legend" aria-label="Route line legend">${relation==='same-route'?item(route,'selected','Selected · Baseline'):item(route,'selected','Selected')+item(baseline,relation==='shared-path'?'shared':'baseline',referenceLabel)}${kind?`<p class="corridor-geometry-kind">${kind}</p>`:''}${showRecorded&&route.id==='air'?'<p class="recorded-flight-key"><i></i>KL896 · 4 Nov · Partial observations</p>':''}</div>${relation==='shared-path'?'<p class="shared-route-note">Same geographic path · Different service, cost and transit time.</p>':''}`;
}
export function mapRoutePicker(selectedId,icon) {
  return `<div class="map-route-picker" role="group" aria-label="Choose a route on the map">${ROUTES.map(route=>`<button data-action="select" data-preview-route="${route.id}" data-value="${route.id}" data-focus="map-choice-${route.id}" aria-label="Choose ${escape(route.name)} on map" aria-pressed="${selectedId===route.id}">${icon({ocean:'ship',rail:'train',multimodal:'mixed',air:'plane'}[route.mode],16)}${labels[route.id]}</button>`).join('')}</div>`;
}
export function mapStopStrip(route,icon,active) {
  return `<nav class="map-stops" aria-label="Explore route locations"><span class="map-stops-label">ROUTE STOPS</span><div>${routeLocations(route).map((stop,i)=>`${i?icon('chevron',12):''}<button data-action="map-location" data-value="${escape(stop.name)}" data-focus="location-${stop.index}" aria-pressed="${active===stop.name}" aria-label="Explore ${escape(stop.name)} on map"><span class="stop-strip-dot ${stop.endpoint?'endpoint':''}"></span>${escape(stop.name)}</button>`).join('')}</div></nav>`;
}

export function routeMap(route,referenceId,{interactive=true,showAll=false,transform='translate(0px, 0px) scale(1)',activeLocation=null,referenceLabel='Baseline',showRecorded=false}={}) {
  const baseline=ROUTES.find(item=>item.id===referenceId),relation=routeRelation(route,baseline),path=roundedRoutePath(route);
  const actions=(r,role)=>interactive?`class="map-route ${role}" role="button" tabindex="0" data-action="select" data-value="${r.id}" data-map-route="${r.id}" data-focus="map-path-${r.id}" aria-label="Select ${escape(r.name)}${role==='baseline'?' '+referenceLabel.toLowerCase():''} on map"`: `class="map-route ${role}" data-map-route="${r.id}"`;
  const selectable=(r,role)=>`<g ${actions(r,role)}><title>${escape(r.name)}</title>${interactive?`<path class="hit-route" d="${roundedRoutePath(r)}"/>`:''}<path class="${role==='baseline'?'baseline-path':'other-route'}" d="${roundedRoutePath(r)}"/><path class="route-trace" d="${roundedRoutePath(r)}"/></g>`;
  const locationMarkup=routeLocations(route).map(location=>{
    const {name,point,endpoint,width,height,role,code}=location;
    return `<g class="map-location ${endpoint?'map-endpoint':''} ${name===activeLocation?'is-active':''}" data-map-location="${escape(name)}" data-map-x="${point[0]}" data-map-y="${point[1]}" data-width="${width}" data-height="${height}" data-endpoint="${endpoint}" data-role="${role}" data-index="${location.index}" transform="translate(${point.join(',')})" ${interactive?`role="button" tabindex="0" data-action="map-location" data-value="${escape(name)}" data-focus="map-location-${location.index}" aria-label="Inspect ${escape(name)} map point"`:''}><g class="map-symbol"><circle class="location-halo" r="10"/><circle class="location-ring ${role.toLowerCase()}" r="${endpoint?5:4}"/>${role==='Destination'?'<circle class="location-core" r="2"/>':''}<circle class="location-active-ring" r="10"/></g><g class="geo-label" transform="translate(${role==='Origin'?-width-12:12},${role==='Origin'?-height-12:12})"><path class="label-leader"/><rect width="${width}" height="${height}" rx="6"/><text class="location-name" x="11" y="${endpoint?19:18}">${escape(name)}</text>${endpoint?`<text class="location-code" x="11" y="35">${code} · ${role}</text>`:''}</g></g>`;
  }).join('');
  const instance=++mapInstance,gridId=`route-grid-${instance}`,waterId=`water-${instance}`,revealId=`route-reveal-${instance}`;
  return `<svg class="route-map" viewBox="0 0 1000 610" role="${interactive?'group':'img'}" data-selected-route="${route.id}" data-mode="${route.mode}" ${interactive?'tabindex="0" data-focus="route-map" aria-describedby="map-navigation-help"':''} aria-label="${escape(route.name)} selected${relation==='distinct'?'; '+escape(baseline.name)+' '+referenceLabel.toLowerCase()+' shown dashed':relation==='shared-path'?'; baseline service shares this path':'; selected route is the baseline'}"><defs><pattern id="${gridId}" width="88.235" height="53.043" patternUnits="userSpaceOnUse"><path d="M88.235 0H0V53.043" fill="none" class="geographic-grid"/></pattern><linearGradient id="${waterId}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--map-water-top)"/><stop offset="1" stop-color="var(--map-water)"/></linearGradient><mask id="${revealId}" maskUnits="userSpaceOnUse" x="-100" y="-100" width="1200" height="810"><path class="route-reveal-mask" pathLength="1" stroke-width="28" d="${path}"/></mask></defs><g class="map-zoom" transform="${transform.replaceAll('px','')}"><rect width="1000" height="610" fill="url(#${waterId})"/><g class="land-surface"><use class="land-layer" href="${geographyHref('land')}"/><use class="map-lakes" href="${geographyHref('lakes')}"/><use class="map-rivers" href="${geographyHref('rivers')}"/><use class="map-borders" href="${geographyHref('borders')}"/></g><rect width="1000" height="610" fill="url(#${gridId})" class="grid-overlay"/><g class="map-labels"><text x="590" y="460" class="ocean-label">INDIAN OCEAN</text><text x="75" y="365" class="ocean-label">ATLANTIC</text><text x="83" y="383" class="ocean-label">OCEAN</text></g>${interactive&&showAll?ROUTES.filter(r=>r.id!==route.id&&r.id!==referenceId).map(r=>selectable(r,'alternative')).join(''):''}${relation==='distinct'?selectable(baseline,'baseline'):''}<g class="selected-route-layer" mask="url(#${revealId})"><path class="selected-path-back" d="${path}"/><path class="selected-path" d="${path}"/>${routeDirections(route).map(arrow=>`<g class="map-direction" transform="translate(${arrow.x},${arrow.y})"><g class="direction-symbol"><g transform="rotate(${arrow.angle})"><path class="direction-halo" d="M-5-3.5 0 0-5 3.5"/><path d="M-5-3.5 0 0-5 3.5"/></g></g></g>`).join('')}${['air','seaair'].includes(route.id)?[[TERMINALS.ams,AMS_ROAD[0]],[AMS_ROAD.at(-1),TERMINALS.rsc],...(route.id==='seaair'?[[TERMINALS.jebelAli,DUBAI_ROAD[0]],[DUBAI_ROAD.at(-1),TERMINALS.dwc]]:[])].map(points=>`<path class="flight-erase" d="${roundedRoutePath({points,mode:'air'})}"/><path class="access-connector" d="${roundedRoutePath({points,mode:'air'})}"/>`).join(''):''}${route.id==='rail'?`<path class="flight-erase" d="${roundedRoutePath({points:CASPIAN_FERRY,mode:'rail'})}"/><path class="flight-connection ferry-connection" d="${roundedRoutePath({points:CASPIAN_FERRY,mode:'rail'})}"/>`:''}${route.id==='air'?`<path class="flight-erase" d="${roundedRoutePath({points:greatCircle(TERMINALS.pvg,TERMINALS.ams),mode:'air'})}"/><path class="flight-connection" d="${roundedRoutePath({points:greatCircle(TERMINALS.pvg,TERMINALS.ams),mode:'air'})}"/>`:''}${route.id==='seaair'?`<path class="flight-erase" d="${roundedRoutePath({points:DUBAI_FLIGHT})}"/><path class="flight-connection" d="${roundedRoutePath({points:DUBAI_FLIGHT})}"/>`:''}</g>${route.id==='air'&&showRecorded?OBSERVED_KL896.map(points=>`<path class="observed-flight" d="${roundedRoutePath({points,mode:'air'})}"/>`).join(''):''}${interactive?'<g class="journey-marker" hidden aria-hidden="true"><g class="journey-marker-symbol"><circle r="9" class="journey-marker-halo"/><circle r="4.5" class="journey-marker-core"/></g></g>':''}</g><g class="geographic-annotations" aria-hidden="true"></g><g class="map-annotations">${locationMarkup}</g></svg>`;
}
